+package com.example;
+
+import java.util.ArrayList;
+import java.util.List;
+
+import org.springframework.stereotype.Service;
+
+/** Shared so messages remain visible after navigating away from the contact view. */
+@Service
+public class ContactMessageStore {
+
+    private final List<ContactMessage> messages = new ArrayList<>();
+
+    public synchronized void add(ContactMessage message) {
+        messages.addFirst(message);
+    }
+
+    public synchronized List<ContactMessage> newestFirst() {
+        return List.copyOf(messages);
+    }
+}
